// canary.go
// Defines the discovery fixture's handler and language-independent answer.
// Connects temporary Go tests and route-doc extraction without registering a real route.
// Exists solely in temporary trees created by the B1a tests.
package canary

import "net/http"

// CanaryHandler returns the fixture answer.
func CanaryHandler(w http.ResponseWriter, r *http.Request) { w.Write([]byte("canary")) }

func Register() { http.HandleFunc("/api/canary", CanaryHandler) }

app/components/canary/backend/canary_tes:
package canary
import (
 "net/http/httptest"
 "testing"
)
func TestCanary(t *testing.T) {
 w := httptest.NewRecorder()
 CanaryHandler(w, httptest.NewRequest("GET", "/api/canary", nil))
 if w.Body.String() != "canary" { t.Fatal("wrong fixture answer") }
}

